#!/bin/sh
# Demo roles for Kabr. LOCAL DEMO ONLY.
#
# Runs once on first start of an empty volume, after 10-pagila.sh, connected
# to the "pagila" database as the "postgres" superuser.
#
# No password is written in this repository. The role passwords are random
# values generated by `make demo-secrets` into deploy/compose/.env.demo
# (gitignored) and passed to the container through docker-compose.yml's
# env_file. psql reads them with \getenv (never on a command line, so they do
# not show up in the process list) and interpolates them with :'var', which
# quotes them as SQL string literals.
set -eu

: "${KABR_READER_PASSWORD:?missing - run 'make demo-secrets' (or make demo-up)}"
: "${KABR_UNSAFE_PASSWORD:?missing - run 'make demo-secrets' (or make demo-up)}"

psql --no-psqlrc --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" --quiet <<'SQL'
\set ON_ERROR_STOP on
\getenv reader_pw KABR_READER_PASSWORD
\getenv unsafe_pw KABR_UNSAFE_PASSWORD

-- The Pagila dump (taken with pre-15 defaults) ends with
-- "GRANT ALL ON SCHEMA public TO PUBLIC", which lets EVERY role create
-- objects in "public". Restore the PostgreSQL 15+ default (USAGE only) so
-- that only roles granted CREATE explicitly can do so.
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- ---------------------------------------------------------------------------
-- kabr_reader: the role Kabr is meant to run as. Least privilege.
-- It can connect, resolve objects in "public" and read table rows if it
-- wanted to (Kabr itself only reads the catalog). No write, no DDL.
-- Note: pg_catalog and information_schema are readable by any role by
-- default; no grant is needed for catalog introspection.
-- ---------------------------------------------------------------------------
CREATE ROLE kabr_reader LOGIN PASSWORD :'reader_pw'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;

GRANT CONNECT ON DATABASE pagila TO kabr_reader;
GRANT USAGE ON SCHEMA public TO kabr_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO kabr_reader;

-- Tables created later by "postgres" in "public" are readable too.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT SELECT ON TABLES TO kabr_reader;

-- ---------------------------------------------------------------------------
-- kabr_unsafe: deliberately over-privileged. It exists only so the demo can
-- show Kabr's least-privilege check warning about a role that can write
-- rows and create objects. Never connect Kabr like this in real life.
-- ---------------------------------------------------------------------------
CREATE ROLE kabr_unsafe LOGIN PASSWORD :'unsafe_pw'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;

GRANT CONNECT ON DATABASE pagila TO kabr_unsafe;
GRANT USAGE, CREATE ON SCHEMA public TO kabr_unsafe;
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA public TO kabr_unsafe;
-- Inserting into tables with serial ids needs the sequences as well.
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA public TO kabr_unsafe;

ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON TABLES TO kabr_unsafe;
SQL
